async function fetchMyReactions(profileId: string): Promise<Record<string, string>> {
  const { data, error } = await createClient().from("post_likes").select("post_id,reaction").eq("profile_id", profileId);
  if (error) throw error;
  const map: Record<string, string> = {};
  for (const row of data ?? []) map[row.post_id as string] = (row.reaction as string) || "like";
  return map;
}
async function savePostReaction(postId: string, profileId: string, reaction: string) {
  const supabase = createClient();
  const { error: deleteError } = await supabase.from("post_likes").delete().eq("post_id", postId).eq("profile_id", profileId);
  if (deleteError) throw deleteError;
  const { error } = await supabase.from("post_likes").insert({ post_id: postId, profile_id: profileId, reaction });
  if (error) throw error;
}
type DiscoverRow = { id: string; auth_user_id: string | null; display_name: string; headline: string | null; avatar_url: string | null; department: string | null; study_year: string | null; interests: string[] | null; member_type?: string | null; university: { name: string } | { name: string }[] | null };
function discoverAvatar(name: string, seed: number) {
  const initials = name.split(/\s+/).filter(Boolean).slice(0, 2).map(part => part[0]?.toUpperCase()).join("") || "C";
  const tone = (seed * 37) % 28 + 32;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" rx="50" fill="hsl(230 5% ${tone}%)"/><text x="50" y="57" text-anchor="middle" dominant-baseline="middle" font-family="Arial" font-size="32" font-weight="700" fill="#fff">${initials}</text></svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}
async function fetchDiscoverPeople(excludeProfileId?: string): Promise<Person[]> {
  const supabase = createClient();
  const build = (withType: boolean) => {
    let request = supabase.from("profiles")
      .select(`id,auth_user_id,display_name,headline,avatar_url,department,study_year,interests,${withType ? "member_type," : ""}university:universities!profiles_university_id_fkey(name)`)
      .not("auth_user_id", "is", null).order("display_name");
    if (excludeProfileId) request = request.neq("id", excludeProfileId);
    return request;
  };
  // Works before and after the member_type SQL has been run.
  const first = await build(true);
  let rows = first.data as unknown as DiscoverRow[] | null;
  let failure = first.error;
  if (failure) { const second = await build(false); rows = second.data as unknown as DiscoverRow[] | null; failure = second.error; }
  if (failure) throw failure;
  let viewerDepartment = "";
  let viewerSchool = "";
  let viewerInterests: string[] = [];
  if (excludeProfileId) {
    const { data: viewer } = await supabase.from("profiles").select("department,interests,university:universities!profiles_university_id_fkey(name)").eq("id", excludeProfileId).maybeSingle();
    const viewerUniversity = Array.isArray(viewer?.university) ? viewer?.university[0] : viewer?.university;
    viewerDepartment = (viewer?.department ?? "").trim().toLowerCase();
    viewerInterests = viewer?.interests ?? [];
    viewerSchool = viewerUniversity?.name ?? "";
  }
  const people: Person[] = (rows ?? []).map((row, index) => {
    const university = Array.isArray(row.university) ? row.university[0] : row.university;
    const alumni = row.member_type === "alumni";
    return { id: index + 1, profileId: row.id, isRegistered: true, name: row.display_name, role: row.headline ?? (alumni ? "Alumni" : "University member"),
      school: university?.name ?? "CONNECT", avatar: row.avatar_url ?? discoverAvatar(row.display_name, index), tag: alumni ? "Alumni" : "Student",
      department: row.department ?? "", studyYear: row.study_year ?? "", interests: row.interests ?? [] };
  });
  const score = (person: Person) => (viewerSchool && person.school === viewerSchool ? 5 : 0)
    + (viewerDepartment && (person.department ?? "").trim().toLowerCase() === viewerDepartment ? 3 : 0)
    + (person.interests ?? []).filter(item => viewerInterests.some(interest => interest.toLowerCase() === item.toLowerCase())).length;
  return people.sort((a, b) => score(b) - score(a) || a.name.localeCompare(b.name));
}
type ProfileExtras = { department: string; studyYear: string; interests: string[]; memberType: string };
function parseInterests(value: string) { return value.split(",").map(item => item.trim()).filter(Boolean).slice(0, 8); }
async function fetchProfileExtras(profileId: string): Promise<ProfileExtras> {
  const supabase = createClient();
  type ExtraRow = { department?: string | null; study_year?: string | null; interests?: string[] | null; member_type?: string | null };
  const full = await supabase.from("profiles").select("department,study_year,interests,member_type").eq("id", profileId).maybeSingle();
  let row = full.data as unknown as ExtraRow | null;
  if (full.error) { const basic = await supabase.from("profiles").select("department,study_year,interests").eq("id", profileId).maybeSingle(); row = basic.data as unknown as ExtraRow | null; }
  return { department: row?.department ?? "", studyYear: row?.study_year ?? "", interests: row?.interests ?? [], memberType: row?.member_type === "alumni" ? "alumni" : "student" };
}
